'use strict';

// The analytics export. A result row arrives as a plain object keyed by column
// name and leaves as a line of CSV text for the finance importer.

function escapeField(value) {
  return '"' + String(value) + '"';
}

function writeRow(fields) {
  return fields.map(escapeField).join(',');
}

function writeCsv(rows) {
  if (!Array.isArray(rows) || rows.length === 0) return '';
  const columns = Object.keys(rows[0]);
  const lines = [writeRow(columns)];
  for (const row of rows) {
    lines.push(writeRow(columns.map((key) => row[key])));
  }
  return lines.join('\n') + '\n';
}

module.exports = { writeRow, writeCsv };

