'use strict';

const { writeCsv } = require('./export.js');

// The download the finance team pulls once a week. Records come off the
// analytics query keyed by our internal field names; the column titles in the
// file are the ones finance reads.
const COLUMN_TITLES = {
  sku: 'SKU',
  label: 'Product',
  units: 'Units',
  revenue: 'Revenue',
};

function toExportRow(record) {
  const out = {};
  for (const key of Object.keys(record)) {
    out[COLUMN_TITLES[key] || key] = record[key] || '';
  }
  return out;
}

function exportReport(records) {
  const rows = records.filter((record) => record.units).map(toExportRow);
  return writeCsv(rows);
}

module.exports = { exportReport, COLUMN_TITLES };

