'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { writeField, writeRow, writeCsv, createCsvWriter, appendRows } = require('./src/export.js');
const { exportReport } = require('./src/report.js');

test('s1 a field is quoted only when the value needs it, and an inner quote is doubled', () => {
  assert.strictEqual(writeField('widget'), 'widget', 'an ordinary value goes out bare');
  assert.strictEqual(writeField('SKU-1'), 'SKU-1');
  assert.strictEqual(writeField('widget, large'), '"widget, large"', 'a separator inside the value forces quotes');
  assert.strictEqual(writeField('line\nbreak'), '"line\nbreak"');
  assert.strictEqual(writeField('carriage\rreturn'), '"carriage\rreturn"');
  assert.strictEqual(writeField('the "large" one'), '"the ""large"" one"', 'an inner quote is doubled');
  assert.strictEqual(writeField('"'), '""""');

  assert.strictEqual(writeRow(['sku-1', 'widget, large', '4']), 'sku-1,"widget, large",4');
  assert.strictEqual(writeRow(['a', 'b']), 'a,b');
});

test('s2 padding on either end forces quotes and the value itself is never trimmed', () => {
  assert.strictEqual(writeField(' Acme'), '" Acme"');
  assert.strictEqual(writeField('Acme '), '"Acme "');
  assert.strictEqual(writeField('\tAcme'), '"\tAcme"');
  assert.strictEqual(writeField('Acme\t'), '"Acme\t"');
  assert.strictEqual(writeField('   '), '"   "', 'a value that is only spaces is still those spaces');

  assert.strictEqual(writeField('Acme Widgets'), 'Acme Widgets', 'a space in the middle is not a reason to quote');
  assert.strictEqual(writeField('a b c'), 'a b c');
  assert.strictEqual(writeRow([' padded ', 'a b']), '" padded ",a b');
});

test('s3 an absent value writes nothing and an empty string writes as a pair of quotes', () => {
  assert.strictEqual(writeField(null), '');
  assert.strictEqual(writeField(undefined), '');
  assert.strictEqual(writeField(''), '""');

  assert.strictEqual(writeRow(['a', null, '', undefined, 'b']), 'a,,"",,b');
  assert.strictEqual(writeRow([null, null]), ',');
  assert.strictEqual(writeRow(['', '']), '"",""');
});

test('s4 the header is every key any row has, in the order the keys are first seen', () => {
  const rows = [
    { sku: 'A-1', label: 'Widget' },
    { label: 'Gadget', region: 'EU' },
    { sku: 'A-3', note: 'x, y' },
  ];
  assert.strictEqual(
    writeCsv(rows),
    'sku,label,region,note\nA-1,Widget,,\n,Gadget,EU,\nA-3,,,"x, y"\n',
    'a column missing from the first row still gets a column of its own'
  );

  assert.strictEqual(writeCsv([]), '', 'no rows is an empty file');
  assert.strictEqual(writeCsv([{ sku: 'A-1' }, { sku: 'A-2' }]), 'sku\nA-1\nA-2\n');
});

test('s5 numbers, booleans and dates go out in the form the warehouse indexes on', () => {
  assert.strictEqual(writeField(1234.5), '1234.5');
  assert.strictEqual(writeField(0), '0');
  assert.strictEqual(writeField(-0), '0', 'a negative zero is just zero');
  assert.strictEqual(writeField(-12), '-12');
  assert.strictEqual(writeField(true), 'true');
  assert.strictEqual(writeField(false), 'false');
  assert.strictEqual(writeField(new Date('2026-03-04T05:06:07.000Z')), '2026-03-04T05:06:07.000Z');

  assert.strictEqual(writeField(new Date('not a date')), '', 'a date that is not a date is no value at all');
  assert.strictEqual(writeField(NaN), '');
  assert.strictEqual(writeField(Infinity), '');
  assert.strictEqual(writeField(-Infinity), '');

  assert.strictEqual(
    writeRow([1, true, null, '', new Date('2026-03-04T05:06:07.000Z')]),
    '1,true,,"",2026-03-04T05:06:07.000Z'
  );
  assert.strictEqual(writeCsv([{ units: 0, sold: false }]), 'units,sold\n0,false\n');
});

test('s6 the line ending is an option and a break inside a value is left as it was written', () => {
  const rows = [{ a: '1', b: 'note' }, { a: '2', b: 'has\nbreak' }];
  assert.strictEqual(writeCsv(rows), 'a,b\n1,note\n2,"has\nbreak"\n');

  const crlf = writeCsv(rows, { crlf: true });
  assert.strictEqual(crlf, 'a,b\r\n1,note\r\n2,"has\nbreak"\r\n', 'the break inside the value is not rewritten');
  assert.ok(crlf.endsWith('\r\n'));
  assert.ok(!crlf.endsWith('\r\n\r\n'), 'exactly one line ending at the end, no blank line after it');

  assert.strictEqual(writeCsv([{ a: 'x\r\ny' }], { crlf: true }), 'a\r\n"x\r\ny"\r\n');
  assert.strictEqual(writeCsv([{ a: 'x\r\ny' }]), 'a\n"x\r\ny"\n');
});

test('s7 the byte order mark is written once at the very front, and only a true switches a flag on', () => {
  const rows = [{ a: '1' }, { a: '2' }];

  const marked = writeCsv(rows, { bom: true });
  assert.strictEqual(marked, '\uFEFFa\n1\n2\n');
  assert.strictEqual(marked.indexOf('\uFEFF', 1), -1, 'the mark appears once and nowhere else');
  assert.strictEqual(writeCsv(rows, { bom: true, crlf: true }), '\uFEFFa\r\n1\r\n2\r\n');
  assert.strictEqual(writeCsv([], { bom: true }), '', 'an empty file has nothing to mark');

  for (const junk of ['true', 1, 'yes', {}, [], null, 0, 'false', 'on', '1', -1, ' true ']) {
    assert.strictEqual(writeCsv(rows, { bom: junk }), 'a\n1\n2\n', 'only the boolean true switches the mark on');
    assert.strictEqual(writeCsv(rows, { crlf: junk }), 'a\n1\n2\n', 'only the boolean true switches CRLF on');
  }

  assert.strictEqual(writeCsv(rows), 'a\n1\n2\n', 'no options at all is the same as no options set');
  assert.strictEqual(writeCsv(rows, null), 'a\n1\n2\n');
  assert.strictEqual(writeCsv(rows, 'nonsense'), 'a\n1\n2\n');
});

test('s8 an explicit column list drives the file, and the report hands its options through', () => {
  const rows = [{ sku: 'A-1', label: 'Widget', region: 'EU' }];
  assert.strictEqual(writeCsv(rows, { columns: ['label', 'sku'] }), 'label,sku\nWidget,A-1\n', 'a key outside the list is left out');
  assert.strictEqual(writeCsv(rows, { columns: ['sku', 'missing'] }), 'sku,missing\nA-1,\n');
  assert.strictEqual(writeCsv([], { columns: ['label', 'sku'] }), 'label,sku\n', 'a column list with no rows behind it is still a header');

  const records = [
    { units: 3, sku: 'A-1', revenue: 30 },
    { label: 'Widget', sku: 'A-2', units: 1, revenue: 10.5 },
  ];
  assert.strictEqual(
    exportReport(records),
    'SKU,Product,Units,Revenue\nA-1,,3,30\nA-2,Widget,1,10.5\n',
    'the map declares the column order, whatever order the record arrived in'
  );
  assert.strictEqual(
    exportReport(records, { crlf: true, bom: true }),
    '\uFEFFSKU,Product,Units,Revenue\r\nA-1,,3,30\r\nA-2,Widget,1,10.5\r\n',
    'the options reach the writer'
  );
  assert.strictEqual(exportReport(records, { columns: ['Units', 'SKU'] }), 'Units,SKU\n3,A-1\n1,A-2\n', "a caller's own column list wins");

  const withExtras = [{ sku: 'A-1', units: 1, region: 'EU' }, { sku: 'A-2', units: 2 }];
  assert.strictEqual(
    exportReport(withExtras),
    'SKU,Units,region\nA-1,1,EU\nA-2,2,\n',
    'a title the map does not know about goes after the ones it does'
  );
});

test('s9 every record reaches the file and the totals line adds up the columns finance names', () => {
  const records = [
    { sku: 'A-1', label: 'Widget', units: 0, revenue: 0 },
    { sku: 'A-2', label: 'Gadget', units: 4, revenue: 10.5 },
    null,
    'not a record',
    { sku: 'A-3', label: 'Gizmo', units: 2, revenue: 20.25 },
  ];
  const body = 'SKU,Product,Units,Revenue\nA-1,Widget,0,0\nA-2,Gadget,4,10.5\nA-3,Gizmo,2,20.25\n';
  assert.strictEqual(exportReport(records), body, 'a zero is a zero, and a record that is not an object is skipped');

  assert.strictEqual(exportReport(records, { totals: ['Units', 'Revenue'] }), body + 'TOTAL,,6,30.75\n');
  assert.strictEqual(exportReport(records, { totals: ['Product'] }), body + 'TOTAL,0,,\n', 'a column with nothing numeric in it totals to 0');
  assert.strictEqual(exportReport(records, { totals: ['SKU'] }), body + 'TOTAL,,,\n', 'the first column reads TOTAL even when the list names it');
  assert.strictEqual(exportReport(records, { totals: ['Nope'] }), body + 'TOTAL,,,\n', 'a title that is not a column here is ignored');
  assert.strictEqual(exportReport(records, { totals: 'Units' }), body, 'a totals field that is not a list adds no row');
  assert.strictEqual(exportReport(records), body, 'no totals field adds no row');
  assert.strictEqual(exportReport([], { totals: ['Units'] }), '', 'no records means no totals row');

  const partial = [{ sku: 'A-1', units: 2 }, { sku: 'A-2', units: NaN }, { sku: 'A-3' }];
  assert.strictEqual(exportReport(partial, { totals: ['Units'] }), 'SKU,Units\nA-1,2\nA-2,\nA-3,\nTOTAL,2\n');
});

test('s10 the streaming writer emits one header and its chunks concatenate into the whole file', () => {
  const rows = [{ sku: 'A-1', units: 1 }, { sku: 'A-2', units: 2 }, { sku: 'A-3', units: 3 }];
  const options = { columns: ['sku', 'units'] };
  const writer = createCsvWriter(options);
  assert.strictEqual(writer.write([]), '', 'an empty chunk commits to nothing');
  const first = writer.write([rows[0]]);
  const second = writer.write([rows[1], rows[2]]);
  const last = writer.end();
  assert.strictEqual(first, 'sku,units\nA-1,1\n', 'the header rides the first chunk that carries a row');
  assert.strictEqual(second, 'A-2,2\nA-3,3\n', 'a later chunk is its own rows and nothing else');
  assert.strictEqual(last, '', 'a writer that has already emitted every row has nothing left at the end');
  assert.strictEqual(first + second + last, writeCsv(rows, options), 'the chunks are the file');
  assert.strictEqual(second.indexOf('sku'), -1, 'the header goes out once');

  const derived = createCsvWriter();
  assert.strictEqual(derived.write([]), '');
  assert.strictEqual(
    derived.write([{ sku: 'A-1', units: 1 }, { sku: 'A-2', label: 'x' }]),
    'sku,units,label\nA-1,1,\nA-2,,x\n',
    'the first chunk that carries a row fixes the header'
  );
  assert.strictEqual(derived.write([{ sku: 'A-3', region: 'EU', units: 9 }]), 'A-3,9,\n', 'a key that is not in the header is left out');
  assert.strictEqual(derived.end(), '');

  const marked = createCsvWriter({ columns: ['sku'], bom: true, crlf: true });
  assert.strictEqual(marked.write([{ sku: 'A-1' }]), '\uFEFFsku\r\nA-1\r\n');
  const nextChunk = marked.write([{ sku: 'A-2' }]);
  assert.strictEqual(nextChunk, 'A-2\r\n');
  assert.strictEqual(nextChunk.indexOf('\uFEFF'), -1, 'the mark rides the first chunk only');

  const emptyReport = createCsvWriter({ columns: ['sku', 'units'] });
  assert.strictEqual(emptyReport.end(), 'sku,units\n', 'a column list and no rows is still a header');
  assert.strictEqual(emptyReport.end(), '', 'ending twice adds nothing');
  assert.strictEqual(createCsvWriter().end(), '', 'with no column list and no rows there is nothing to write');

  const closed = createCsvWriter({ columns: ['sku'] });
  closed.write([{ sku: 'A-1' }]);
  closed.end();
  assert.strictEqual(closed.write([{ sku: 'A-2' }]), '', 'nothing comes out after the end');
});

test('s11 the separator and the quote mode reach every field, and the absent rules outrank both', () => {
  assert.strictEqual(writeField('a;b', { separator: ';' }), '"a;b"');
  assert.strictEqual(writeField('a,b', { separator: ';' }), 'a,b', 'a comma is only special when it is the separator');
  assert.strictEqual(writeRow(['a', 'b'], { separator: ';' }), 'a;b');
  assert.strictEqual(writeCsv([{ a: 'x;y', b: 'p,q' }], { separator: ';' }), 'a;b\n"x;y";p,q\n');
  for (const junk of ['', ';;', 5, null, undefined, '"', '\n', '\r', [';']]) {
    assert.strictEqual(writeRow(['a', 'b'], { separator: junk }), 'a,b', 'an unusable separator falls back to a comma');
  }

  assert.strictEqual(writeField('a', { quote: 'all' }), '"a"');
  assert.strictEqual(writeField(5, { quote: 'all' }), '"5"');
  assert.strictEqual(writeField('he said "hi"', { quote: 'all' }), '"he said ""hi"""');
  assert.strictEqual(writeField('a', { quote: 'strings' }), '"a"');
  assert.strictEqual(writeField(5, { quote: 'strings' }), '5');
  assert.strictEqual(writeField(true, { quote: 'strings' }), 'true');
  assert.strictEqual(writeField(new Date('2026-03-04T05:06:07.000Z'), { quote: 'strings' }), '2026-03-04T05:06:07.000Z');

  for (const mode of ['all', 'strings']) {
    assert.strictEqual(writeField(null, { quote: mode }), '', 'an absent value is absent whatever the mode');
    assert.strictEqual(writeField(undefined, { quote: mode }), '');
    assert.strictEqual(writeField('', { quote: mode }), '""', 'an empty string is a pair of quotes whatever the mode');
  }
  for (const junk of ['minimal', 'ALL', 'Strings', true, 1, null, {}]) {
    assert.strictEqual(writeField('a', { quote: junk }), 'a', 'an unusable mode falls back to minimal');
  }

  assert.strictEqual(writeField(15, { separator: '5' }), '"15"', 'minimal quoting is a floor, whatever the value started as');
  assert.strictEqual(writeField(15, { separator: '5', quote: 'strings' }), '"15"');

  assert.strictEqual(writeCsv([{ a: 'x', b: 5 }], { quote: 'all' }), '"a","b"\n"x","5"\n');
  const writer = createCsvWriter({ columns: ['a'], separator: ';', quote: 'all' });
  assert.strictEqual(writer.write([{ a: 'x' }]), '"a"\n"x"\n', 'the streaming writer honours both as well');
});

test('s12 appendRows continues an existing file instead of starting a new one', () => {
  const existing = 'SKU,Product\nA-1,Widget\n';
  const row = [{ SKU: 'A-2', Product: 'Gadget' }];

  assert.strictEqual(appendRows(existing, row), 'A-2,Gadget\n', 'no second header');
  assert.strictEqual(appendRows('SKU,Product\nA-1,Widget', row), '\nA-2,Gadget\n', 'a missing terminator is written first');
  assert.strictEqual(appendRows('SKU,Product\r\nA-1,Widget\r\n', row), 'A-2,Gadget\r\n', 'the line ending is the one the file already uses');
  assert.strictEqual(appendRows(existing, row, { crlf: true }), 'A-2,Gadget\n', 'the file wins over the option');
  assert.strictEqual(appendRows('SKU,Product', row, { crlf: true }), '\r\nA-2,Gadget\r\n', 'with no line break in the file the option decides');

  assert.strictEqual(appendRows('\uFEFFSKU,Product\nA-1,Widget\n', row), 'A-2,Gadget\n', 'the mark is not part of the first title and no second one is written');
  assert.strictEqual(appendRows('\uFEFFSKU,Product\nA-1,Widget\n', row, { bom: true }), 'A-2,Gadget\n', 'appending to a file that has a mark never writes a second one');
  assert.strictEqual(
    appendRows('"Product, long",SKU\nWidget,A-1\n', [{ 'Product, long': 'Gadget', SKU: 'A-2' }]),
    'Gadget,A-2\n',
    'a title with the separator inside it is one title'
  );
  assert.strictEqual(
    appendRows('"he said ""hi""",SKU\nx,A-1\n', [{ 'he said "hi"': 'y', SKU: 'A-2' }]),
    'y,A-2\n',
    'a doubled quote in a title is one quote'
  );
  assert.strictEqual(
    appendRows('"two\nline",SKU\nx,A-1\n', [{ 'two\nline': 'y', SKU: 'A-2' }]),
    'y,A-2\n',
    'a line break inside a title does not end the header'
  );
  assert.strictEqual(appendRows('SKU;Product\nA-1;Widget\n', row, { separator: ';' }), 'A-2;Gadget\n');

  assert.strictEqual(appendRows(existing, [{ SKU: 'A-2', region: 'EU' }]), 'A-2,\n', 'a key the header does not have is left out, a column the row does not have is absent');
  assert.strictEqual(appendRows(existing, []), '', 'nothing to append');
  assert.strictEqual(appendRows(existing, null), '');

  const fresh = [{ SKU: 'A-1', Product: 'Widget' }];
  assert.strictEqual(appendRows('', fresh, { bom: true }), writeCsv(fresh, { bom: true }), 'no file yet means writing the whole file');
  assert.strictEqual(appendRows(null, fresh), writeCsv(fresh));
});

