'use strict';

// The analytics export. A result row arrives as a plain object keyed by column
// name and leaves as a line of CSV text for the finance importer.

const DEFAULT_SEPARATOR = ',';
// U+FEFF, written out as an escape so it is visible in this file.
const BOM = '\uFEFF';

function optionsFrom(options) {
  return options && typeof options === 'object' ? options : {};
}

// A separator is one character and cannot be a character the quoting rule owns.
function separatorFrom(opts) {
  const raw = opts.separator;
  if (typeof raw === 'string' && raw.length === 1 && raw !== '"' && raw !== '\r' && raw !== '\n') {
    return raw;
  }
  return DEFAULT_SEPARATOR;
}

// Only the boolean itself switches a flag on: the caller reads these out of a
// query string, where every value is a truthy string.
function eolFrom(opts) {
  return opts.crlf === true ? '\r\n' : '\n';
}

function bomFrom(opts) {
  return opts.bom === true ? BOM : '';
}

function quoteModeFrom(opts) {
  return opts.quote === 'all' || opts.quote === 'strings' ? opts.quote : 'minimal';
}

// An absent value and an empty string are different facts about a record, so
// they are kept apart here: absent comes back as null and writes nothing at
// all, while '' writes as a pair of quotes.
function coerce(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'string') return { text: value, wasString: true };
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) return null;
    return { text: String(value === 0 ? 0 : value), wasString: false };
  }
  if (typeof value === 'boolean') return { text: String(value), wasString: false };
  if (value instanceof Date) {
    if (Number.isNaN(value.getTime())) return null;
    return { text: value.toISOString(), wasString: false };
  }
  return { text: String(value), wasString: false };
}

function needsQuoting(text, separator) {
  if (text.includes(separator) || text.includes('"') || text.includes('\r') || text.includes('\n')) {
    return true;
  }
  // The importer trims a bare field, so padding has to be protected.
  return /^[ \t]/.test(text) || /[ \t]$/.test(text);
}

function quote(text) {
  return '"' + text.replace(/"/g, '""') + '"';
}

function writeField(value, options) {
  const opts = optionsFrom(options);
  const cell = coerce(value);
  if (cell === null) return '';
  if (cell.text === '') return '""';
  // Minimal quoting is a floor rather than an alternative to the mode.
  if (needsQuoting(cell.text, separatorFrom(opts))) return quote(cell.text);
  const mode = quoteModeFrom(opts);
  if (mode === 'all') return quote(cell.text);
  if (mode === 'strings' && cell.wasString) return quote(cell.text);
  return cell.text;
}

function writeRow(fields, options) {
  const opts = optionsFrom(options);
  const list = Array.isArray(fields) ? fields : [];
  return list.map((field) => writeField(field, opts)).join(separatorFrom(opts));
}

// Every key that appears in any row, in the order the keys are first seen.
function unionColumns(rows) {
  const columns = [];
  const seen = new Set();
  for (const row of rows) {
    if (!row || typeof row !== 'object') continue;
    for (const key of Object.keys(row)) {
      if (seen.has(key)) continue;
      seen.add(key);
      columns.push(key);
    }
  }
  return columns;
}

function columnsFor(rows, opts) {
  return Array.isArray(opts.columns) ? opts.columns.slice() : unionColumns(rows);
}

function lineFor(row, columns, opts) {
  const source = row && typeof row === 'object' ? row : {};
  return writeRow(columns.map((column) => source[column]), opts);
}

function writeCsv(rows, options) {
  const opts = optionsFrom(options);
  const list = Array.isArray(rows) ? rows : [];
  const columns = columnsFor(list, opts);
  if (columns.length === 0) return '';
  const eol = eolFrom(opts);
  let out = bomFrom(opts) + writeRow(columns, opts) + eol;
  for (const row of list) out += lineFor(row, columns, opts) + eol;
  return out;
}

// Incremental writing for reports too large to hold in memory. The header goes
// out once, in front of the first chunk that carries a row, and is fixed from
// that point on.
function createCsvWriter(options) {
  const opts = optionsFrom(options);
  const eol = eolFrom(opts);
  let columns = Array.isArray(opts.columns) ? opts.columns.slice() : null;
  let started = false;
  let ended = false;

  function header() {
    started = true;
    return bomFrom(opts) + writeRow(columns, opts) + eol;
  }

  return {
    write(rows) {
      if (ended) return '';
      const list = Array.isArray(rows) ? rows : [];
      if (list.length === 0) return '';
      if (columns === null) {
        const derived = unionColumns(list);
        if (derived.length === 0) return '';
        columns = derived;
      }
      let out = started ? '' : header();
      for (const row of list) out += lineFor(row, columns, opts) + eol;
      return out;
    },
    end() {
      if (ended) return '';
      ended = true;
      if (!started && columns !== null && columns.length > 0) return header();
      return '';
    },
  };
}

// The first record of an existing file, which is not the same as its first
// physical line: a column title may carry a line break inside its quotes.
function firstRecord(text) {
  let inQuotes = false;
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (ch === '"') {
      if (inQuotes && text[i + 1] === '"') {
        i += 1;
        continue;
      }
      inQuotes = !inQuotes;
    } else if (!inQuotes && (ch === '\n' || ch === '\r')) {
      return { line: text.slice(0, i), eol: ch === '\r' && text[i + 1] === '\n' ? '\r\n' : ch };
    }
  }
