'use strict';

const { writeCsv } = require('./export.js');

// The download the finance team pulls once a week. Records come off the
// analytics query keyed by our internal field names; the column titles in the
// file are the ones finance reads.
const COLUMN_TITLES = {
  sku: 'SKU',
  label: 'Product',
  units: 'Units',
  revenue: 'Revenue',
};

const TITLE_ORDER = Object.keys(COLUMN_TITLES).map((key) => COLUMN_TITLES[key]);

function toExportRow(record) {
  const out = {};
  for (const key of Object.keys(record)) {
    out[COLUMN_TITLES[key] || key] = record[key];
  }
  return out;
}

// Mapped titles in the order the map declares them, then anything the map does
// not know about, in the order it is first seen.
function orderedColumns(rows) {
  const seen = new Set();
  const extras = [];
  for (const row of rows) {
    for (const key of Object.keys(row)) {
      if (seen.has(key)) continue;
      seen.add(key);
      if (!TITLE_ORDER.includes(key)) extras.push(key);
    }
  }
  return TITLE_ORDER.filter((title) => seen.has(title)).concat(extras);
}

function totalsRow(rows, columns, totals) {
  const row = {};
  row[columns[0]] = 'TOTAL';
  for (const title of totals) {
    if (title === columns[0] || !columns.includes(title)) continue;
    let sum = 0;
    for (const source of rows) {
      const value = source[title];
      if (typeof value === 'number' && Number.isFinite(value)) sum += value;
    }
    row[title] = sum;
  }
  return row;
}

function exportReport(records, options) {
  const opts = options && typeof options === 'object' ? options : {};
  const list = Array.isArray(records) ? records : [];
  const rows = [];
  for (const record of list) {
    if (!record || typeof record !== 'object') continue;
    rows.push(toExportRow(record));
  }
  const columns = Array.isArray(opts.columns) ? opts.columns.slice() : orderedColumns(rows);
  const out = rows.slice();
  if (rows.length > 0 && columns.length > 0 && Array.isArray(opts.totals)) {
    out.push(totalsRow(rows, columns, opts.totals));
  }
  return writeCsv(out, Object.assign({}, opts, { columns }));
}

module.exports = { exportReport, COLUMN_TITLES };
